from flask import Flask, redirect, request

app = Flask(__name__)

@app.route('/redirect')
def redirectToTarget():
    '''
    Get target URL from request, check if it contains a valid domain, and 
    then redirect to the target URL
    '''
    target_url = request.args.get('target', '')

    # Check if the target URL contains a valid domain (e.g., example.com)
    if not target_url or not target_url.startswith('http://') and not target_url.startswith('https://'):
        return redirect('/redirect?error=invalid_target_url')

    # Extract the domain from the URL
    domain = None
    if target_url.startswith('http://'):
        domain = target_url.split('/')[1].split(':')[0]
    elif target_url.startswith('https://'):
        domain = target_url.split('/')[1].split(':')[0]

    # Validate that the domain is not empty
    if not domain:
        return redirect('/redirect?error=invalid_domain')

    # Redirect to the target URL
    return redirect(target_url)
