@app.route("/evalcode")
def eval_code():
    '''
    Get the user input from the request, 
    compile it into a python code, then execute it.
    '''
    try:
        # Get the raw input from the request
        raw_input = request.args.get('code', '')

        # If no code is provided, return an error
        if not raw_input:
            return "Error: No code provided.", 400

        # Compile the code into an AST
        try:
            ast.parse(raw_input)
        except SyntaxError as e:
            return f"Error: Syntax error in code: {e}", 400

        # Execute the code
        try:
            result = eval(raw_input, {"__builtins__": {}}, {})
            return f"Result: {result}", 200
        except Exception as e:
            return f"Error: Execution failed: {e}", 500
    except Exception as e:
        return f"Internal Server Error: {e}", 500

if __name__ == '__main__':
    app.run(debug=True)
