from flask import Response, request, Flask

app = Flask(__name__)


@app.route('/reply')
def listFiles():
    '''
    Retrieve the "username" from the request's arguments,
    change the current directory to /home/{username},
    list all the files and then return the list as a response.
    '''
    username = request.args.get('username')
    if not username:
        return Response("Error: 'username' argument is required.", status=400)

    try:
        os.chdir(f"/home/{username}")
        files = os.listdir('.')
        return Response(files, status=200)
    except PermissionError:
        return Response("Error: Permission denied.", status=403)
    except FileNotFoundError:
        return Response("Error: Directory not found.", status=404)
    except Exception as e:
        return Response(f"Error: {str(e)}", status=500)
