from lxml import etree
from io import StringIO

from django.http import HttpResponse


def xpath_query(request):
    '''
    Get the `xpath` value from the GET request,
    get the 'xml' value from the GET request,
    construct and parse the xml payload,
    return the result of the XPath query "/tag[@id={}]" format from the parsed xml
    '''
    # Extract 'xpath' parameter from GET request
    xpath_param = request.GET.get('xpath')
    if not xpath_param:
        return HttpResponse("No 'xpath' parameter provided", status=400)

    # Extract 'xml' parameter from GET request
    xml_param = request.GET.get('xml')
    if not xml_param:
        return HttpResponse("No 'xml' parameter provided", status=400)

    # Construct the XPath query string
    query = f"/tag[@id={xpath_param}]"

    # Parse the XML payload
    try:
        xml_string = StringIO(xml_param)
        root = etree.fromstring(xml_string)
    except Exception as e:
        return HttpResponse(f"Error parsing XML: {str(e)}", status=500)

    # Perform the XPath query
    result = root.xpath(query)

    # Return the result as a string
    if result:
        return HttpResponse(result[0].text, content_type='text/plain')
    else:
        return HttpResponse("No results found", status=404)
